import {component$, Slot} from '@builder.io/qwik';

/**
 * Mirrors upstream's `MatHint` (`src/material/form-field/directives/hint.ts`).
 * `id` is normally generated by the owning `<MatFormField>` (via
 * {@link import('../core/mat-form-field-control').readControlProps} reading
 * this component's `id` prop off its JSX descriptor and injecting a
 * generated one when absent — see `mat-form-field.tsx`'s "id ownership" —
 * NOT by this component itself, unlike upstream's own
 * `inject(_IdGenerator)` field initializer); pass an explicit `id` only to
 * override that.
 *
 * Pass the result as `<MatFormField hintStart={<MatHint>...</MatHint>}
 * hintEnd={<MatHint align="end">...</MatHint>}>` — not as a nested child —
 * see `mat-form-field.tsx`'s doc comment for why.
 */
export interface MatHintProps {
  /** Whether to align the hint label at the start or end of the line.
   *  Default `'start'`. */
  align?: 'start' | 'end';
  id?: string;
  class?: string | ReadonlyArray<string>;
}

export const MatHint = component$<MatHintProps>(props => {
  const align = props.align ?? 'start';
  const classes = [
    'mat-mdc-form-field-hint',
    'mat-mdc-form-field-bottom-align',
    align === 'end' && 'mat-mdc-form-field-hint-end',
    props.class,
  ].filter(Boolean) as string[];
  return (
    <mat-hint id={props.id} class={classes}>
      <Slot />
    </mat-hint>
  );
});
